  const int group_idx      = by / tiles_per_group;
  const int tile_in_group  = by % tiles_per_group;
  const int oc_base        = group_idx * Cout_per_group + tile_in_group * OcPerBlockMax;
  const int oc_count_full  = Cout_per_group - tile_in_group * OcPerBlockMax;
  const int oc_count       = oc_count_full < OcPerBlockMax ? oc_count_full : OcPerBlockMax;

  const int Cin_start = group_idx * Cin_per_group;
  const int R   = Cin_per_group * K * K * K;
  const int KKK = K * K * K;
  const int KK  = K * K;

