  int Cin  = (int)x_c.size(1);
  int D    = (int)x_c.size(2);
  int H    = (int)x_c.size(3);
  int Win  = (int)x_c.size(4);

  int Cout          = (int)w_c.size(0);
  int Cin_per_group = (int)w_c.size(1);
  int K             = (int)w_c.size(2);
  TORCH_CHECK((int)w_c.size(3) == K && (int)w_c.size(4) == K, "kernel must be cubic");

  TORCH_CHECK(groups > 0, "groups must be > 0");
  TORCH_CHECK(Cin % groups == 0, "Cin must be divisible by groups");
  TORCH_CHECK(Cout % groups == 0, "Cout must be divisible by groups");
  TORCH_CHECK(Cin_per_group == Cin / groups, "weight Cin_per_group mismatch");

  int Cout_per_group = Cout / groups;

  TORCH_CHECK(stride > 0 && dilation > 0, "stride and dilation must be > 0");
  TORCH_CHECK(padding >= 0, "padding must be >= 0");

